// EMAIL ENROLMENT WITHOUT A HUMAN CLICK — and what replaces the click.
//
// The Slack approval was removed from the EMAIL leg on the owner's instruction: the goal is 15-20
// outreach a day and approving each one individually does not scale. It is still in place for the
// agent's own tool (VIO-agent-tool-push-instantly), and it must stay there, because that path lets
// an LLM CHOOSE the recipients. Here a human already chose every recipient by typing them into the
// Inbox tab. That is the whole justification for this workflow existing separately, and if leads
// ever start arriving here from an automated source, the gate has to come back.
//
// The human was doing five jobs. Each is now a check that THROWS:
//   1. "is this a real address"      -> verification must have passed, or a human vouched by name
//   2. "have they asked us to stop"  -> the suppression list is re-read at send time, not trusted
//   3. "is this the right company"   -> the product must resolve to a real campaign
//   4. "does the email read right"   -> the AI-written opener is sanity-checked
//   5. "is this too many"            -> a hard daily cap, counted from what actually sent
//
// Same structure as the gated tool: nothing downstream has a URL of its own. The Instantly
// endpoint is produced ONLY past these throws, so a rewire that skips this node does not produce
// an unchecked send, it produces an HTTP node with nothing to call.

const CAP_PER_DAY = 20;          // the owner's stated ceiling of 15-20/day
const MAX_PER_RUN = 5;

const CAMPAIGNS = {
  oryoniq: { id: '77b2cd80-5bf2-4656-8857-b310858d5a77', name: 'OryonIQ - Reach Engine Pilot (2026-08)' },
  // Deliberately null until a VisioneerIT campaign exists in Instantly. Null refuses with a reason;
  // omitting the key would refuse with "unknown product", which sends someone hunting the wrong bug.
  visioneerit: null,
};

// ⚠️ READ THE REQUEST FROM THE TRIGGER BY NAME, NOT FROM $input.
// Two Google Sheets reads sit between the trigger and this node (suppression, then events), and a
// Sheets node's output is ITS ROWS. Reading $input here got the last sheet row and refused every
// call with "no leads supplied". This is the THIRD time this exact shape has bitten this build in
// one day — any node that reads a value from further upstream than its immediate predecessor must
// name the node it wants.
const req = $('Called by Workflow').first().json || {};
const leads = Array.isArray(req.leads) ? req.leads : [];
if (!leads.length) throw new Error('REFUSED: no leads supplied.');
if (leads.length > MAX_PER_RUN) {
  throw new Error(`REFUSED: ${leads.length} leads in one call exceeds the per-run cap of ${MAX_PER_RUN}.`);
}

const key = String(req.product || '').toLowerCase().replace(/[^a-z]/g, '');
if (!key) throw new Error('REFUSED: no product named — refusing to guess which company is pitching.');
if (!(key in CAMPAIGNS)) {
  throw new Error(`REFUSED: unknown product '${req.product}'. Known: ${Object.keys(CAMPAIGNS).join(', ')}`);
}
const campaign = CAMPAIGNS[key];
if (!campaign) {
  throw new Error(`REFUSED: ${key} has no Instantly campaign yet, so there is nothing to enrol into. Create one and add its id here.`);
}

// ---- 2. SUPPRESSION, re-read now rather than trusted from upstream ----------------------------
// Append-only and matched on ANY identifier. Someone may have opted out since this lead was
// drafted; the whole point of re-reading is that the list moves under us.
// ⚠️ SUPPRESSION MUST MATCH THE PERSON, NOT THE STRING.
//
// Exact string matching was bypassable three ways, all proven 2026-08-30:
//   * plus-addressing — suppressed a@x.com, re-contacted as a+anything@x.com
//   * subdomains      — suppressed x.com, re-contacted at mail.x.com
//   * zero-width characters invisibly inserted into the address
// Someone on this list has ASKED US TO STOP. A near-miss that still delivers mail is the failure
// this list exists to prevent, so both sides are normalised to a canonical form before comparing.
const ZW = /[​-‏⁠﻿­]/g;   // zero-width + soft hyphen
const canon = (s) => String(s == null ? '' : s).replace(ZW, '').trim().toLowerCase();

// Gmail-style +tags and dots are the same mailbox to most providers; strip the tag always, and
// keep BOTH forms so a list entry written either way still matches.
const emailKeys = (raw) => {
  const e = canon(raw);
  const at = e.lastIndexOf('@');
  if (at < 1) return e ? [e] : [];
  const local = e.slice(0, at), dom = e.slice(at + 1);
  const untagged = local.split('+')[0];
  const keys = new Set([e, `${untagged}@${dom}`]);
  return [...keys].filter(Boolean);
};

// Suppressing a domain must cover its subdomains: opting out of x.com and then being mailed at
// mail.x.com is the same person receiving the same unwanted mail.
const domainChain = (host) => {
  const h = canon(host).replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  const parts = h.split('.').filter(Boolean);
  const out = [];
  for (let i = 0; i + 1 < parts.length; i++) out.push(parts.slice(i).join('.'));
  return out;   // mail.x.com -> ['mail.x.com', 'x.com']
};

const supp = new Set();
for (const it of $('Read Suppression').all()) {
  const raw = (it.json || {}).identifier_value;
  for (const k of emailKeys(raw)) supp.add(k);
  const v = canon(raw);
  if (v && v.indexOf('@') === -1) for (const dchain of domainChain(v)) supp.add(dchain);
  else if (v) supp.add(v);
}

// ---- 5. DAILY CAP, counted from what actually sent -------------------------------------------
// Counted off the Events log, not off an internal tally: a counter this workflow keeps in its own
// head resets whenever it restarts, and would happily send another 20.
// "Today" means the SENDING TEAM'S day, not the UTC day. Both sides of this comparison used to be
// UTC, which is self-consistent but wrong: a US working day straddles two UTC dates, so the cap
// silently reset around 8pm Detroit and 20/day became 40 in one afternoon-and-evening. The
// heartbeat nodes already report in America/Detroit; this now agrees with them.
const TZ = 'America/Detroit';
const localDay = (d) => {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
  } catch (e) {
    return d.toISOString().slice(0, 10);   // fail toward the stricter UTC day rather than not counting
  }
};
const today = localDay(new Date());
let sentToday = 0;
for (const it of $('Read Events').all()) {
  const e = it.json || {};
  if (String(e.tool || '').toLowerCase() !== 'instantly') continue;
  if (String(e.action || '').toLowerCase() !== 'enroll') continue;
  const ts = new Date(String(e.timestamp || ''));
  // An unparseable timestamp COUNTS. Skipping it would let a malformed Events row raise the cap.
  if (isNaN(ts.getTime()) || localDay(ts) === today) sentToday += 1;
}
if (sentToday >= CAP_PER_DAY) {
  throw new Error(`REFUSED: ${sentToday} leads already enrolled today, at the daily cap of ${CAP_PER_DAY}. Nothing sent.`);
}
const room = CAP_PER_DAY - sentToday;
if (leads.length > room) {
  throw new Error(`REFUSED: ${leads.length} leads would pass the daily cap (${sentToday} already sent, ${room} left today).`);
}

const EMAIL = /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/;
const BANNED = [/\{\{/, /\}\}/, /\[\[/, /lorem ipsum/i, /as an ai/i, /^here'?s?\b/i,
                /placeholder/i, /TODO/, /undefined/, /\bnull\b/];

const bodies = [];
for (const l of leads) {
  // Canonical form, so an invisible character cannot smuggle an address past the checks below.
  const email = canon((l && l.contact_email) || '');
  if (!EMAIL.test(email)) throw new Error(`REFUSED: '${email}' is not a single valid address.`);

  // ---- 1. VERIFIED, or vouched for by a person -----------------------------------------------
  // 'pass' is Reoon's verdict. 'approved' is a human overriding it for one named address, which is
  // how a catch-all domain gets through — a catch-all accepts mail for ANY address, so no verifier
  // can confirm a mailbox on it, and only somebody who knows the person can say it is real.
  const verdict = String(l.verify_action || '').toLowerCase();
  const state = String(l.channel_state_email || '').toLowerCase();
  // A vouch is a judgement call about an AMBIGUOUS address. It is not a veto over a definite
  // negative: if Reoon says the mailbox does not exist, no amount of human confidence makes it
  // deliverable, and mailing it just earns a bounce against the sending domain. Checked before the
  // vouch is consulted so the ordering cannot be reversed by a later edit.
  if (verdict === 'drop' || verdict === 'invalid') {
    throw new Error(`REFUSED: ${email} was rejected by verification ('${verdict}'). That is a verified negative, not a judgement call — a human vouch cannot override it.`);
  }
  if (verdict !== 'pass' && state !== 'approved') {
    throw new Error(`REFUSED: ${email} is '${verdict || 'unverified'}' and nobody vouched for it. Only a verified address or an explicit human approval may be mailed.`);
  }

  // ---- 2. suppression, on every identifier we hold ------------------------------------------
  // Compare canonical forms on BOTH sides: the lead's address with its +tag stripped, and every
  // parent domain of its host.
  const candidates = new Set(emailKeys(email));
  for (const dchain of domainChain(email.split('@')[1] || '')) candidates.add(dchain);
  for (const extra of [l.linkedin_url, l.phone]) {
    const c = canon(extra);
    if (c) candidates.add(c);
  }
  for (const id of candidates) {
    if (supp.has(id)) {
      throw new Error(`REFUSED: ${email} matches the suppression list on '${id}'. That person asked us to stop. Nothing sent.`);
    }
  }

  // ---- 4. the AI-written line, sanity-checked in the human's place --------------------------
  // This is the ONLY part of the email a model writes; everything else is fixed campaign copy.
  // With nobody reading it before it goes, an unrendered merge tag or a chatbot preamble would
  // reach a real prospect.
  const opener = String(l.opener || '').trim();
  if (opener.length < 20) throw new Error(`REFUSED: ${email} has no usable opening line (${opener.length} chars).`);
  if (opener.length > 400) throw new Error(`REFUSED: ${email} has a ${opener.length}-char opening line; something went wrong upstream.`);
  for (const re of BANNED) {
    if (re.test(opener)) throw new Error(`REFUSED: ${email}'s opening line matches ${re} — it looks unrendered or machine-leaked, not like copy.`);
  }
  // The opener is interpolated into an HTML email body AND onto a public page. Nothing the model
  // writes has any business carrying markup or a link: every legitimate URL in this campaign is
  // fixed copy or the {{sendrPageUrl}} merge tag. A model that has been talked into emitting a
  // link is the difference between a bad sentence and us phishing our own prospect.
  if (/<[a-z/][^>]*>/i.test(opener)) {
    throw new Error(`REFUSED: ${email}'s opening line contains HTML markup. The opener is plain text only.`);
  }
  if (/\b(?:https?:\/\/|www\.)\S/i.test(opener) || /\b[a-z0-9-]+\.(?:com|net|org|io|ai|co|gov|edu|ru|cn|xyz|link)\b\S*\//i.test(opener)) {
    throw new Error(`REFUSED: ${email}'s opening line contains a URL. Links in this campaign come from fixed copy, never from the model.`);
  }
  if (ZW.test(opener)) {
    throw new Error(`REFUSED: ${email}'s opening line contains zero-width characters.`);
  }

  // ---- 3. the page the campaign CTA points at ------------------------------------------------
  const page = String(l.sendr_page_url || '').trim();
  if (!/^https?:\/\//.test(page)) {
    throw new Error(`REFUSED: ${email} has no Sendr page URL. Step 1's CTA is {{sendrPageUrl}} and would render empty.`);
  }

  bodies.push({
    campaign: campaign.id,
    email,
    first_name: String(l.first_name || ''),
    company_name: String(l.company || ''),
    personalization: opener,
    // TOP-LEVEL, never nested under `payload`: Instantly silently discards custom variables nested
    // there and still answers 201, so the CTA renders as a bare colon to a real prospect.
    custom_variables: { sendrPageUrl: page, firstName: String(l.first_name || ''), companyName: String(l.company || '') },
    skip_if_in_campaign: true,
  });
}

const INSTANTLY_LEADS_URL = 'https://api.instantly.ai/api/v2/leads';
return bodies.map((body, i) => ({ json: {
  instantly_url: INSTANTLY_LEADS_URL,
  instantly_body: body,
  email: body.email,
  index: i,
  product: key,
  campaign_id: campaign.id,
  campaign_name: campaign.name,
  sent_today_before: sentToday,
  daily_cap: CAP_PER_DAY,
  authorized_at: new Date().toISOString(),
} }));

// What actually happened, per lead, in terms a human can audit later.
//
// ⚠️ Instantly answers 201 for a lead it did NOT create. skip_if_in_campaign is WORKSPACE-wide, so
// an address already present anywhere in the workspace comes back 200/201 carrying the PRE-EXISTING
// lead id and nothing is added. A previous version of this pipeline reported "enrolled: 2" while
// the campaign held zero. The only honest signal is whether the returned lead's campaign matches
// the one we asked for.
const auth = $('Preconditions (fail closed)').all().map((i) => i.json);
const out = [];
$input.all().forEach((item, i) => {
  const res = item.json || {};
  const a = auth[i] || {};
  const returnedCampaign = String(res.campaign || res.campaign_id || '');
  const created = Boolean(res.id) && returnedCampaign === String(a.campaign_id || '');
  out.push({ json: {
    email: a.email,
    product: a.product,
    campaign_id: a.campaign_id,
    campaign_name: a.campaign_name,
    instantly_lead_id: res.id || '',
    enrolled: created,
    note: created ? 'lead created in the campaign'
      : 'Instantly returned a lead that is NOT in this campaign — it already existed somewhere in the workspace, so nothing was added',
    sendr_page_url: (a.instantly_body && a.instantly_body.custom_variables && a.instantly_body.custom_variables.sendrPageUrl) || '',
    opener: (a.instantly_body && a.instantly_body.personalization) || '',
    daily_cap: a.daily_cap,
    sent_today_before: a.sent_today_before,
    at: new Date().toISOString(),
  }});
});
return out;

// Two tabs, one shape per row. Only leads Instantly ACTUALLY created advance the lifecycle —
// reporting a send that did not happen is worse than reporting nothing.
const rows = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const now = new Date().toISOString();
  if (r.enrolled) {
    rows.push({ json: { _kind: 'lead',
      contact_email: r.email, channel_state_email: 'enrolled', Product: r.product,
      sendr_page_url: r.sendr_page_url, opener: r.opener, updated_at: now } });
  }
  rows.push({ json: { _kind: 'event',
    timestamp: now, lead_email: r.email, tool: 'instantly',
    action: r.enrolled ? 'enroll' : 'enroll_noop',
    units: r.enrolled ? 1 : 0,
    result: r.note, workflow: 'VIO-enrol-email', lead_id: r.instantly_lead_id,
    // Measured, never estimated — the project rule. Blank means nobody measured it.
    est_cost_usd: '', source_config: r.product } });
}
return rows;
